  "lane_fidelity": {
    "score": 10,
    "assessment": "Lane correctness is strong. The candidate stays within the Data/sql slice, under src/data/schema and src/data/migrations, with tests under test/data/schema. It does not introduce backend, frontend, infra, or stray bootstrap/config wrappers."
  },
